bounded_host_request.command:
set -euo pipefail
mapfile -t ids < <(docker ps -q --filter label=com.docker.compose.service=gaybbs)
test "${#ids[@]}" -eq 1 || exit 60
cid="${ids[0]}"
docker exec "$cid" test -r /run/secrets/bug_report_recipient || exit 61
docker exec -i "$cid" node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module <<'JS'
import {readFileSync} from "node:fs";
const token=readFileSync("/run/secrets/bot_token","utf8").trim();
const recipient=readFileSync("/run/secrets/bug_report_recipient","utf8").trim();
if(!/^[0-9]+$/.test(recipient)||!token)process.exit(62);
try {
 const response=await fetch("https://api.telegram.org/bot"+token+"/sendMessage",{
  method:"POST",
  headers:{"content-type":"application/json"},
  body:JSON.stringify({chat_id:recipient,text:"🐞 不具合報告通知の接続テスト（実際の不具合報告ではありません）"})
 });
 const data=await response.json();
 if(response.ok&&data.ok&&String(data.result?.chat?.id)===recipient&&Number.isSafeInteger(data.result?.message_id)){
  console.log("REPORT_OPERATOR_DM_DELIVERY=PASS");
 }else{
  console.log("REPORT_OPERATOR_DM_DELIVERY=FAIL");
  process.exitCode=63;
 }
}catch{
 console.log("REPORT_OPERATOR_DM_DELIVERY=UNKNOWN");
 process.exitCode=64;
}
JS
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 65
echo USERBOT_SERVICE_PRESERVED=PASS
